package com.bplus.share;import org.json.*;
public class TestNearby125{static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError(n);}public static void main(String[]a)throws Exception{Nearby.gate.visible(true);String ip="192.168.1.10",secret="0123456789abcdef0123456789abcdef";JSONObject r=Nearby.handle("/nearby/request",new JSONObject().put("secret",secret).put("profile",new JSONObject().put("id","sender")),ip);String id=r.getString("request");JSONObject req=new JSONObject().put("request",id).put("secret",secret);ok(r.getString("status").equals("pending"));ok(Store.saved==null);Nearby.gate.decide(id,"accepted",System.currentTimeMillis());JSONObject status=Nearby.handle("/nearby/status",req,ip);ok(status.getString("status").equals("accepted"));ok(status.getJSONObject("profile").getString("id").equals("receiver"));ok(Store.saved==null);req.put("token","senderToken12345678");try{Nearby.handle("/nearby/confirm",req,ip);throw new AssertionError();}catch(java.io.IOException expected){n++;}req.put("pairEpoch","bad");try{Nearby.handle("/nearby/confirm",req,ip);throw new AssertionError();}catch(java.io.IOException expected){n++;}String epoch=UnpairWire.nearby(id,secret);req.put("pairEpoch",epoch);JSONObject done=Nearby.handle("/nearby/confirm",req,ip);ok(done.getString("status").equals("paired"));ok(epoch.equals(done.getString("pairEpoch")));ok(Store.saved.getString("id").equals("sender"));ok(Store.saved.getString("pairEpoch").equals(epoch));ok(Nearby.handle("/nearby/confirm",req,ip).getString("status").equals("paired"));ok(Nearby.handle("/nearby/status",req,ip).getString("pairEpoch").equals(epoch));Nearby.gate.visible(false);try{Nearby.handle("/nearby/status",req,ip);throw new AssertionError();}catch(java.io.IOException expected){n++;}System.out.println("PASS "+n+" exact Nearby.handle gate/handshake assertions via persistence shims. Not live devices.");System.exit(0);}}
